<?php
namespace xdecaro\Component\Inventory\Administrator\Model;
defined('_JEXEC') or die; use Joomla\CMS\MVC\Model\BaseDatabaseModel; use Joomla\Database\ParameterType;
final class DashboardModel extends BaseDatabaseModel { public function getSummary():array{$db=$this->getDatabase();$active=1;$aggregate=$db->createQuery()->select('COUNT(*) AS total_items')->select('SUM(CASE WHEN '.$db->quoteName('state').' = :active THEN 1 ELSE 0 END) AS active_items')->select('COALESCE(SUM('.$db->quoteName('quantity').'), 0) AS total_quantity')->from($db->quoteName('#__xdecaroinventory_items'))->bind(':active',$active,ParameterType::INTEGER);$db->setQuery($aggregate);$totals=(array)($db->loadAssoc()?:[]);$recent=$db->createQuery()->select(['m.id','m.item_id','m.quantity_delta','m.reason','m.note','m.created','m.created_by'])->select($db->quoteName('i.name','item_name'))->select($db->quoteName('i.sku','item_sku'))->from($db->quoteName('#__xdecaroinventory_movements','m'))->join('INNER',$db->quoteName('#__xdecaroinventory_items','i').' ON '.$db->quoteName('i.id').' = '.$db->quoteName('m.item_id'))->order($db->quoteName('m.created').' DESC');$db->setQuery($recent,0,8);return ['total_items'=>(int)($totals['total_items']??0),'active_items'=>(int)($totals['active_items']??0),'total_quantity'=>(string)($totals['total_quantity']??'0.000'),'recent_movements'=>$db->loadObjectList()?:[]];} }
